import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Ge.css";

function Generate() {
  const navigate = useNavigate();
  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const [isFading, setIsFading] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [effects, setEffects] = useState({
    grain: 15,
    scanlines: 15,
    saturation: 50,
    pixelation: 0,
  });
  const [timestamp, setTimestamp] = useState(new Date());

  const getColorPalette = (imageData, numColors = 5) => {
    const data = imageData.data;
    const colorMap = new Map();

    // Sample colors with higher precision
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const a = data[i + 3];

      // Skip transparent pixels
      if (a < 128) continue;

      // Quantize colors to reduce noise while maintaining color richness
      const quantizedR = Math.round(r / 16) * 16;
      const quantizedG = Math.round(g / 16) * 16;
      const quantizedB = Math.round(b / 16) * 16;

      const colorKey = `${quantizedR},${quantizedG},${quantizedB}`;
      colorMap.set(colorKey, (colorMap.get(colorKey) || 0) + 1);
    }

    // Sort colors by frequency and get the top N colors
    const sortedColors = Array.from(colorMap.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, numColors)
      .map(([colorKey]) => colorKey.split(',').map(Number));

    return sortedColors;
  };

  const splitContourIntoPieces = (contour, numPieces) => {
    const pieces = [];
    const points = [...contour];

    // Calculate bounding box
    const minX = Math.min(...points.map(p => p.x));
    const maxX = Math.max(...points.map(p => p.x));
    const minY = Math.min(...points.map(p => p.y));
    const maxY = Math.max(...points.map(p => p.y));

    // Split into pieces
    for (let i = 0; i < numPieces; i++) {
      const startIdx = Math.floor((i * points.length) / numPieces);
      const endIdx = Math.floor(((i + 1) * points.length) / numPieces);

      const piecePoints = points.slice(startIdx, endIdx);
      if (piecePoints.length < 3) continue;

      pieces.push({
        points: piecePoints,
        minX,
        maxX,
        minY,
        maxY,
        area: (maxX - minX) * (maxY - minY)
      });
    }

    return pieces;
  };

  const calculateOverlap = (x, y, width, height, angle, placedPieces) => {
    let totalOverlap = 0;

    for (const piece of placedPieces) {
      // Simple rectangle overlap calculation
      const dx = Math.abs(x - piece.x);
      const dy = Math.abs(y - piece.y);

      if (dx < (width + piece.width) / 2 && dy < (height + piece.height) / 2) {
        const overlapArea = Math.min(width, piece.width) * Math.min(height, piece.height);
        totalOverlap += overlapArea;
      }
    }

    return totalOverlap;
  };

  const findContours = async (canvas) => {
    const ctx = canvas.getContext('2d');
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const contours = [];
    let currentContour = null;

    // Simple edge detection and contour tracing
    for (let y = 0; y < canvas.height; y++) {
      for (let x = 0; x < canvas.width; x++) {
        const i = (y * canvas.width + x) * 4;
        if (data[i] > 128) { // White pixel
          if (!currentContour) {
            currentContour = [{x, y}];
            contours.push(currentContour);
          } else {
            currentContour.push({x, y});
          }
        } else {
          currentContour = null;
        }
      }
    }

    // Filter out tiny contours
    return contours.filter(contour => contour.length > 10);
  };

  const initializeCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return null;

    const ctx = canvas.getContext("2d");
    if (!ctx) return null;

    return { canvas, ctx };
  };

  useEffect(() => {
    const generatedImage = localStorage.getItem("generatedImage");
    if (!generatedImage) {
      console.error("No generated image found in localStorage");
      setIsLoading(false);
      return;
    }

    const canvasInit = initializeCanvas();
    if (!canvasInit) {
      console.error("Failed to initialize canvas");
      setIsLoading(false);
      return;
    }

    const { canvas, ctx } = canvasInit;
    const img = new Image();

    img.onload = () => {
      // Clear canvas and draw the base image
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      // Generate the piece-based composition
      generateImage();
      setIsLoading(false);
    };

    img.onerror = () => {
      console.error("Failed to load image");
      setIsLoading(false);
    };

    img.src = generatedImage;
    setTimestamp(new Date());

    return () => {
      localStorage.removeItem("generatedImage");
    };
  }, []);

  const handleEffectChange = (effect, value) => {
    setEffects(prev => ({ ...prev, [effect]: value }));
    generateImage();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage();
      setIsFading(false);
    }, 300);
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const generateImage = async () => {
    const canvasInit = initializeCanvas();
    if (!canvasInit) {
      console.error("Failed to initialize canvas for image generation");
      return;
    }

    const { canvas, ctx } = canvasInit;

    // Further reduce canvas size for processing
    const scale = 0.25; // Process at quarter size
    const processWidth = canvas.width * scale;
    const processHeight = canvas.height * scale;

    // Create a temporary canvas for processing
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = processWidth;
    tempCanvas.height = processHeight;
    const tempCtx = tempCanvas.getContext('2d');

    // Scale down the image for processing
    tempCtx.drawImage(canvas, 0, 0, processWidth, processHeight);

    // Get the current image data from the smaller canvas
    const imageData = tempCtx.getImageData(0, 0, processWidth, processHeight);

    // Simplified color palette - just use black and white
    const colorPalette = [[0, 0, 0], [255, 255, 255]];

    // Create binary masks with larger steps
    const masks = await Promise.all(colorPalette.map(async (color) => {
      const maskCanvas = document.createElement('canvas');
      maskCanvas.width = processWidth;
      maskCanvas.height = processHeight;
      const maskCtx = maskCanvas.getContext('2d');

      for (let i = 0; i < imageData.data.length; i += 32) {  // Much larger step size
        const r = imageData.data[i];
        const g = imageData.data[i + 1];
        const b = imageData.data[i + 2];

        // Simplified color comparison
        const isClose = Math.abs(r - color[0]) < 40;
        maskCtx.fillStyle = isClose ? 'white' : 'black';
        maskCtx.fillRect((i/4) % processWidth, Math.floor((i/4) / processWidth), 8, 8);  // Much larger pixels
      }

      return maskCanvas;
    }));

    // Create pieces from each mask with minimal pieces
    const pieces = [];
    for (const mask of masks) {
      const contours = await findContours(mask);
      const color = colorPalette[masks.indexOf(mask)];

      // Split each contour into very few pieces
      for (const contour of contours) {
        const piecesFromContour = splitContourIntoPieces(contour, 2);  // Only 2 pieces per contour
        pieces.push(...piecesFromContour.map(piece => ({
          ...piece,
          color
        })));
      }
    }

    // Clear main canvas and prepare for new composition
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Sort pieces by size (largest first)
    pieces.sort((a, b) => b.area - a.area);

    // Place pieces from center with minimal attempts
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const placedPieces = [];

    for (const piece of pieces) {
      const width = piece.maxX - piece.minX;
      const height = piece.maxY - piece.minY;
      const area = width * height;

      let bestPosition = null;
      let bestOverlap = Infinity;

      for (let attempt = 0; attempt < 5; attempt++) {  // Only 5 attempts
        const angle = Math.random() * Math.PI * 2;
        const distance = Math.random() * 50;  // Reduced distance
        const direction = Math.random() * Math.PI * 2;

        const x = centerX + Math.cos(direction) * distance;
        const y = centerY + Math.sin(direction) * distance;

        const overlap = calculateOverlap(x, y, width, height, angle, placedPieces);

        if (overlap < bestOverlap) {
          bestOverlap = overlap;
          bestPosition = { x, y, angle };
        }

        if (overlap < area * 0.1) {  // Increased overlap tolerance
          break;
        }
      }

      if (bestPosition) {
        ctx.save();
        ctx.translate(bestPosition.x, bestPosition.y);
        ctx.rotate(bestPosition.angle);

        // Simplified piece drawing
        ctx.beginPath();
        ctx.rect(-width/2, -height/2, width, height);  // Draw rectangles instead of complex shapes
        ctx.fillStyle = `rgb(${piece.color.join(',')})`;
        ctx.fill();
        ctx.restore();

        placedPieces.push({
          x: bestPosition.x,
          y: bestPosition.y,
          width,
          height,
          angle: bestPosition.angle
        });
      }
    }

    // Simplified effects
    if (effects.grain > 0) {
      // Simplified grain effect
      const grainData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = grainData.data;
      for (let i = 0; i < data.length; i += 16) {  // Process fewer pixels
        const noise = Math.random() * effects.grain;
        data[i] = Math.min(255, data[i] + noise);
        data[i + 1] = Math.min(255, data[i + 1] + noise);
        data[i + 2] = Math.min(255, data[i + 2] + noise);
      }
      ctx.putImageData(grainData, 0, 0);
    }

    if (effects.scanlines > 0) {
      // Simplified scanlines
      ctx.fillStyle = `rgba(0,0,0,${effects.scanlines/100})`;
      for (let y = 0; y < canvas.height; y += 4) {  // Wider scanlines
        ctx.fillRect(0, y, canvas.width, 2);
      }
    }

    if (effects.saturation !== 50) {
      // Simplified saturation
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      const factor = effects.saturation / 50;
      for (let i = 0; i < data.length; i += 16) {  // Process fewer pixels
        const gray = (data[i] + data[i + 1] + data[i + 2]) / 3;
        data[i] = gray + (data[i] - gray) * factor;
        data[i + 1] = gray + (data[i + 1] - gray) * factor;
        data[i + 2] = gray + (data[i + 2] - gray) * factor;
      }
      ctx.putImageData(imageData, 0, 0);
    }
  };

  return (
    <div ref={containerRef} className="ge-container">
      <button
        onClick={() => navigate('/ho')}
        className="ge-button ge-button-back"
      >
        Go Back
      </button>

      <div className="ge-control-panel">
        <div className="ge-control-group">
          <label className="ge-control-label">Grain: {effects.grain}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.grain}
            onChange={(e) => handleEffectChange('grain', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Scanlines: {effects.scanlines}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.scanlines}
            onChange={(e) => handleEffectChange('scanlines', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Saturation: {effects.saturation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.saturation}
            onChange={(e) => handleEffectChange('saturation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Pixelation: {effects.pixelation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.pixelation}
            onChange={(e) => handleEffectChange('pixelation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
      </div>

      {isLoading ? (
        <div style={{ 
          position: 'absolute', 
          top: '50%', 
          left: '50%', 
          transform: 'translate(-50%, -50%)',
          color: 'white',
          fontSize: '24px'
        }}>
          Loading...
        </div>
      ) : (
        <canvas
          ref={canvasRef}
          width={1080}
          height={1080}
          className="ge-canvas"
          style={{ opacity: isFading ? 0.2 : 1 }}
        />
      )}

      <div className="ge-timestamp">
        {timestamp.toLocaleString()}
      </div>

      <div className="ge-button-container">
        <button
          onClick={handleRegenerate}
          className="ge-button ge-button-regenerate"
        >
          Regenerate
        </button>
        <button
          onClick={handleDownload}
          className="ge-button ge-button-download"
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
